:root {
    --primary-color: #4a90e2;
    --secondary-color: #f5f5f5;
    --text-dark: #333;
    --shadow-light: 0 4px 12px rgba(0, 0, 0, 0.1);
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: 'Poppins', sans-serif;
    background-color: #eaf4ff;
    color: var(--text-dark);
    line-height: 1.6;
}

header {
    background-color: var(--primary-color);
    color: white;
    padding: 40px 20px;
    text-align: center;
    box-shadow: 0 3px 10px rgba(0, 0, 0, 0.15);
}

header h1 {
    margin-bottom: 5px;
    font-size: 2.5rem;
}

header p {
    opacity: 0.9;
    font-size: 1.1rem;
}

/* --- GALERÍA Y CARRUSEL --- */
.gallery-container {
    padding: 40px 20px;
    max-width: 1200px;
    margin: 0 auto;
    text-align: center;
}

.carousel-wrapper {
    /* Establecer un contenedor visible que limita la vista */
    overflow: hidden;
    margin-bottom: 20px;
    padding: 10px 0;
    border: 1px solid #ddd;
    border-radius: 10px;
    background-color: #fff;
    box-shadow: var(--shadow-light);
}

.carousel-track {
    display: flex;
    transition: transform 0.5s ease-in-out; /* Animación principal del carrusel */
    width: fit-content; /* Permite que el track sea tan ancho como sus hijos */
}

.sticker-card {
    flex: 0 0 320px; /* Cada tarjeta ocupa un ancho fijo de 320px */
    background-color: #ffffff;
    border-radius: 12px;
    box-shadow: 0 6px 15px rgba(0, 0, 0, 0.08);
    margin-right: 20px; /* Espacio entre tarjetas */
    overflow: hidden;
    transition: transform 0.3s ease;
    text-align: left;
}

.sticker-card:hover {
    transform: translateY(-5px) scale(1.02);
    box-shadow: 0 10px 20px rgba(0, 0, 0, 0.15);
}

.sticker-card img {
    width: 100%;
    height: 280px; /* Altura fija para consistencia */
    object-fit: cover;
    display: block;
}

.info-card {
    padding: 20px;
}

.info-card h3 {
    color: var(--primary-color);
    margin-bottom: 5px;
}

.info-card p {
    margin-bottom: 15px;
    font-size: 0.95rem;
}

/* Botones de Navegación */
.nav-btn {
    padding: 10px 20px;
    margin: 10px 10px 20px;
    border: none;
    border-radius: 5px;
    background-color: #ccc;
    cursor: pointer;
    font-size: 1rem;
    transition: background-color 0.3s;
    box-shadow: 0 2px 5px rgba(0, 0, 0, 0.1);
}

.nav-btn:hover {
    background-color: #999;
}

/* --- LEYENDA --- */
.legend {
    background-color: #ffffff;
    padding: 30px;
    border-radius: 12px;
    box-shadow: var(--shadow-light);
    margin-top: 40px;
    text-align: center;
}

.legend h2 {
    margin-bottom: 25px;
    color: var(--primary-color);
}

.legend-item {
    display: flex;
    align-items: center;
    margin-bottom: 15px;
    font-size: 1.1rem;
}

.legend-item span {
    padding: 5px 15px;
    border-radius: 20px;
    font-weight: 700;
    margin-right: 20px;
    display: inline-block;
}

/* Colores de Rareza */
.common { background-color: #d4eaf7; color: #1a527a; }
.rare { background-color: #f9e79f; color: #b7950b; }
.epic { background-color: #d2f7d0; color: #27ae60; }
.mythic { background-color: #d6b3ff; color: #6c3483; }

/* --- FOOTER --- */
footer {
    text-align: center;
    padding: 20px;
    background-color: #333;
    color: #aaa;
    margin-top: 50px;
}

document.addEventListener('DOMContentLoaded', () => {
    const track = document.getElementById('stickerCarousel');
    const nextBtn = document.getElementById('nextBtn');
    const prevBtn = document.getElementById('prevBtn');

    const cards = document.querySelectorAll('.sticker-card');

    // Determinar cuántas tarjetas mostrar visiblemente (en este caso, 3)
    const cardsVisible = 3; 

    // Calcular el ancho total de la 'ventana' de visualización
    const wrapper = document.querySelector('.carousel-wrapper');
    const cardWidthWithMargin = 320 + 20; // Ancho del card + margen derecho
    const totalVisibleWidth = cardsVisible * cardWidthWithMargin;

    let currentIndex = 0;
    const totalCards = cards.length;

    // Inicializar la posición del carrusel (asegurar que el ancho de visualización sea correcto)
    // Para que el carrusel parezca que solo muestra 3 elementos a la vez, 
    // ajustaremos la lógica de desplazamiento.

    /**
     * Función para actualizar la transformación CSS del carrusel.
     * Mueve el track basado en el índice de la tarjeta más a la izquierda.
     */
    function updateCarousel() {
        // Calculamos cuánto debe moverse el track en píxeles.
        // Movemos el track de forma que el elemento en el índice 'currentIndex' comience a verse alineado.
        const offset = -currentIndex * (cardsVisible * cardWidthWithMargin - 20); // -20 compensa el último margen
        track.style.transform = `translateX(${offset}px)`;

        // Habilitar/deshabilitar botones
        prevBtn.disabled = currentIndex <= 0;
        nextBtn.disabled = currentIndex >= totalCards - cardsVisible;
    }

    function goToNext() {
        if (currentIndex < totalCards - cardsVisible) {
            currentIndex++;
            updateCarousel();
        }
    }

    function goToPrev() {
        if (currentIndex > 0) {
            currentIndex--;
            updateCarousel();
        }
    }

    // Event Listeners
    nextBtn.addEventListener('click', goToNext);
    prevBtn.addEventListener('click', goToPrev);

    // Inicialización
    // Ajustamos el índice inicial para que muestre las primeras 'cardsVisible' tarjetas sin sobrepasar el límite.
    currentIndex = Math.min(0, totalCards - cardsVisible); 
    updateCarousel();


    // *** Implementación del "Pasar" Automático (Auto-Scroll) ***
    let autoScrollInterval = setInterval(() => {
        // Intentamos avanzar automáticamente, pero solo si no estamos en el final
        if (!nextBtn.disabled && currentIndex < totalCards - cardsVisible) {
            goToNext();
        }
    }, 4000); // Cambiar cada 4 segundos

    // Pausar auto-scroll al hacer hover sobre la galería
    const galleryWrapper = document.querySelector('.gallery-container');
    galleryWrapper.addEventListener('mouseenter', () => {
        clearInterval(autoScrollInterval);
    });

    // Reanudar auto-scroll al dejar de hacer hover
    galleryWrapper.addEventListener('mouseleave', () => {
        autoScrollInterval = setInterval(() => {
            if (!nextBtn.disabled && currentIndex < totalCards - cardsVisible) {
                goToNext();
            }
        }, 4000);
    });
});

